seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"): continue
        seq += line.strip()

genetic_code = {
 'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L',
 'ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V',
 'TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
 'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
 'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
 'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
 'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
 'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G',
}

def revcomp(s):
    comp = {'A':'T','T':'A','C':'G','G':'C'}
    return ''.join(comp[c] for c in reversed(s))

# Find ORFs (start to stop) in all 6 frames
def find_orfs(s, frame, minlen=100):
    orfs = []
    i = frame
    start = None
    while i + 3 <= len(s):
        codon = s[i:i+3]
        if codon == 'ATG' and start is None:
            start = i
        if codon in ('TAA','TAG','TGA') and start is not None:
            orfs.append((start, i+3, i+3-start, s[start:i+3]))
            start = None
        i += 3
    # trailing
    if start is not None:
        orfs.append((start, len(s), len(s)-start, s[start:]))
    return orfs

all_orfs = []
for f in range(3):
    for (st,en,ln,sub) in find_orfs(seq, f, 0):
        all_orfs.append((f, '+', st, en, ln))
for f in range(3):
    rc = revcomp(seq)
    for (st,en,ln,sub) in find_orfs(rc, f, 0):
        all_orfs.append((f, '-', st, en, ln))

all_orfs.sort(key=lambda x: -x[4])
print("=== Longest ORFs (>= 150 aa = 450 nt) ===")
for f,strand,st,en,ln in all_orfs:
    if ln >= 450:
        print(f"strand {strand} frame {f}: nt {st+1}-{en}  length {ln} nt = {ln//3} aa  ({ln%3} remainder)")
print("Total ORFs found:", len(all_orfs))
print("Count >= 300 nt:", sum(1 for o in all_orfs if o[4]>=300))
